-- Types: DATETIME(n) -> DATETIME2(n) (UTC, SYSUTCDATETIME()); JSON -> NVARCHAR(MAX) +
-- ISJSON check; ENUM -> VARCHAR + IN check; text -> NVARCHAR, Latin1_General_100_CI_AS_SC;
-- CHAR(26) ids -> Latin1_General_100_BIN2; AUTO_INCREMENT -> IDENTITY; UNSIGNED widened
-- where SQL Server's signed type would be too small.
--
-- MySQL sets these on every UPDATE (ON UPDATE CURRENT_TIMESTAMP); SQL Server has no
-- such clause, so the statement that updates the row sets them:
--   abuse_rule_overrides.updated_at, abuse_rules.updated_at, account_secrets.updated_at,
