CREATE TABLE [webhook_delivery_alerts] (
  [id] BIGINT IDENTITY(1,1) NOT NULL,
  [endpoint_id] BIGINT NOT NULL,
  [account_id] BIGINT NOT NULL,
  [kind] VARCHAR(3) COLLATE Latin1_General_100_CI_AS_SC NOT NULL,
  [url] NVARCHAR(512) COLLATE Latin1_General_100_CI_AS_SC NOT NULL,
  [first_failed_at] DATETIME2(0) NOT NULL,
  [last_failed_at] DATETIME2(0) NOT NULL,
  [given_up_count] BIGINT NOT NULL CONSTRAINT [DF_webhook_delivery_alerts_given_up_count] DEFAULT (0),
  [failed_count] BIGINT NOT NULL CONSTRAINT [DF_webhook_delivery_alerts_failed_count] DEFAULT (0),
  [last_error] NVARCHAR(255) COLLATE Latin1_General_100_CI_AS_SC NULL,
  [notified_at] DATETIME2(0) NULL,
  [notified_count] BIGINT NOT NULL CONSTRAINT [DF_webhook_delivery_alerts_notified_count] DEFAULT (0),
  [created_at] DATETIME2(0) NOT NULL CONSTRAINT [DF_webhook_delivery_alerts_created_at] DEFAULT (SYSUTCDATETIME()),
  [updated_at] DATETIME2(0) NOT NULL CONSTRAINT [DF_webhook_delivery_alerts_updated_at] DEFAULT (SYSUTCDATETIME()),
  CONSTRAINT [PK_webhook_delivery_alerts] PRIMARY KEY ([id]),
  CONSTRAINT [CK_webhook_delivery_alerts_kind] CHECK ([kind] IN ('dlr', 'mo'))
);
CREATE INDEX [idx_unnotified] ON [webhook_delivery_alerts] ([notified_at], [last_failed_at]);
CREATE UNIQUE INDEX [uq_endpoint] ON [webhook_delivery_alerts] ([endpoint_id]);
